-- Live ticket blocks at the end of five launch posts (the scams guide keeps its guarantee call to action; the Taylor Swift post already has a live block through its live_search setting). The posts' text is not changed: shortcodes are appended (see inc/blog-render.php for what each one shows).
-- The article template already puts a lead form in the middle of every long post and the guide-specific call to action at the end.
UPDATE `blog_posts` SET `content` = CONCAT(`content`, '\n\n[events category="concerts" limit="6" title="Popular concerts on sale right now"]\n') WHERE `slug` = 'upcoming-concert-tours' AND `content` NOT LIKE '%[events category="concerts" limit="6" ti%';
UPDATE `blog_posts` SET `content` = CONCAT(`content`, '\n\n[events city="Austin, TX" limit="6" title="Events in Austin on sale right now"]\n\n<p><small>Check the age guidance on each event page before you buy.</small></p>\n') WHERE `slug` = 'kids-events-in-austin' AND `content` NOT LIKE '%[events city="Austin, TX" limit="6" titl%';
UPDATE `blog_posts` SET `content` = CONCAT(`content`, '\n\n[events city="New York" category="concerts" limit="6" title="Concerts in New York on sale right now"]\n\n[events venue="Madison Square Garden" limit="4"]\n\n[events venue="Radio City Music Hall" limit="4"]\n') WHERE `slug` = 'best-concerts-in-nyc' AND `content` NOT LIKE '%[events city="New York" category="concer%';
UPDATE `blog_posts` SET `content` = CONCAT(`content`, '\n\n[events city="New York" category="theatre" limit="6" title="Broadway and theater in New York right now"]\n\n[events venue="Radio City Music Hall" limit="4"]\n') WHERE `slug` = 'things-to-do-in-nyc-in-december' AND `content` NOT LIKE '%[events city="New York" category="theatr%';
UPDATE `blog_posts` SET `content` = CONCAT(`content`, '\n\n[events category="concerts" limit="6" title="Popular concerts on sale right now"]\n\n[events venue="Red Rocks Amphitheatre" limit="4"]\n\n[events venue="Ryman Auditorium" limit="4"]\n') WHERE `slug` = 'best-concert-venues-in-the-us' AND `content` NOT LIKE '%[events category="concerts" limit="6" ti%';
